#!/usr/bin/env node
// clud-bug#262 item 6 — every `SPEC §x.y` cited under src/ or templates/
// must name a section that exists in the current SPEC (data/spec-sections.json,
// generated by scripts/gen-spec-sections.mjs). A citation that names a
// pre-rewrite section number (SPEC 2.0 tops out at §8.3 — §1.8.1, §7.2.1,
// §10.3.3 etc. do not exist) sends a reader who cross-references it nowhere.
//
//   node scripts/check-spec-citations.mjs
//
// Scope is deliberately narrow: only src/** and templates/** — the surfaces
// a user or another agent actually reads a citation from (--help text,
// stderr, code comments, rendered workflow prompts). Not scripts/, not
// data/spec-sections.json itself, not docs — a citation IN this script's own
// comments about which numbers are stale would otherwise flag itself.

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, relative } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

const SCAN_ROOTS = ['src', 'templates'];

/** A citation is any `§N(.N)*` appearing on a line that also mentions SPEC —
 * covers both "SPEC §7.3" and "SPEC 2.0 §4.7" shapes without over-fitting to
 * one exact prefix wording (both appear in this codebase today).
 */
const CITATION_RE = /§(\d+(?:\.\d+)*)/g;

function walk(dir, out = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, out);
    } else {
      out.push(full);
    }
  }
  return out;
}

function loadSectionIndex(path) {
  const raw = JSON.parse(readFileSync(path, 'utf8'));
  return new Set(raw.sections.map((s) => s.number));
}

/**
 * Scans `text` line by line and returns `{ line, number }` for every
 * `§N(.N)*` citation on a line that also contains the literal `SPEC`.
 * Exported so a test can drive it directly without touching the filesystem.
 */
export function findCitations(text) {
  const found = [];
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line.includes('SPEC')) continue;
    for (const m of line.matchAll(CITATION_RE)) {
      found.push({ line: i + 1, number: m[1] });
    }
  }
  return found;
}

/**
 * Checks every file's citations against `validSections`. Returns a list of
 * `{ file, line, number }` for citations naming a section that isn't in the
 * index. Exported (alongside `findCitations`) so tests can supply a fake
 * index/text pair without touching the filesystem — the control this
 * script's own test suite relies on to prove a fake citation fails.
 */
export function checkText(file, text, validSections) {
  return findCitations(text)
    .filter(({ number }) => !validSections.has(number))
    .map(({ line, number }) => ({ file, line, number }));
}

function main() {
  const indexPath = join(ROOT, 'data', 'spec-sections.json');
  let validSections;
  try {
    validSections = loadSectionIndex(indexPath);
  } catch (err) {
    console.error(`::error::check-spec-citations: could not read ${relative(ROOT, indexPath)} (${err.message}). Run \`node scripts/gen-spec-sections.mjs\` first.`);
    process.exit(1);
  }

  const violations = [];
  for (const root of SCAN_ROOTS) {
    const dir = join(ROOT, root);
    let stat;
    try {
      stat = statSync(dir);
    } catch {
      continue;
    }
    if (!stat.isDirectory()) continue;
    for (const file of walk(dir)) {
      const text = readFileSync(file, 'utf8');
      const rel = relative(ROOT, file);
      violations.push(...checkText(rel, text, validSections));
    }
  }

  if (violations.length > 0) {
    for (const v of violations) {
      console.error(`::error file=${v.file},line=${v.line}::check-spec-citations: SPEC §${v.number} — no such section in the current SPEC (see data/spec-sections.json)`);
    }
    console.error(
      `\ncheck-spec-citations: ${violations.length} stale citation(s) across ${new Set(violations.map((v) => v.file)).size} file(s). ` +
        'Map each to the SPEC 2.0 section that carries the same obligation, or to the policy name the code actually implements — never delete without replacing.',
    );
    process.exit(1);
  }

  console.log(`check-spec-citations: ok (spec ${JSON.parse(readFileSync(indexPath, 'utf8')).specVersion})`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}
